from __future__ import annotations
import argparse
from .common import record, run_purpose

PURPOSE = 'testing'
CATALOG = [{'id': 'test-serialization-properties', 'concept': 'serialization-property-tests', 'domain': 'software-engineering', 'subdomain': 'serialization', 'difficulty': 'intermediate', 'task_type': 'testing', 'verification_method': 'rubric', 'question': 'Design property-based tests for a serializer/deserializer used in a persistent cache. Ordinary example tests have missed edge cases in nested data and unusual strings.', 'answer': "Generate values across the supported schema, including empty collections, boundary numeric values, Unicode, nested structures, and optional fields.\n\nA core property is round-trip equivalence: `decode(encode(x))` must equal `x` under the data model's defined equality. If encoding is required to be canonical, also test that equivalent values produce the same bytes and that decoding then re-encoding reaches the canonical representation.\n\nGenerate malformed/truncated inputs separately and require clean rejection without crashes or excessive resource use. Preserve failing seeds/examples so regressions become deterministic tests.", 'verification_details': 'Must include round-trip properties, boundary/nested data, malformed-input rejection, canonicalization if required, and reproducible shrinking/seeds.', 'tags': ['property-testing', 'serialization', 'roundtrip', 'fuzzing']}, {'id': 'test-short-write-injection', 'concept': 'short-write-fault-injection', 'domain': 'systems-programming', 'subdomain': 'io-testing', 'difficulty': 'advanced', 'task_type': 'testing', 'verification_method': 'rubric', 'question': 'Design a test that proves a buffered output routine correctly handles `write()` returning fewer bytes than requested and being interrupted by signals.', 'answer': 'Wrap or substitute the low-level write operation with a deterministic fault-injection layer. Feed a known buffer while the fake writer returns a planned sequence such as partial counts, `EINTR`, more partial counts, then success.\n\nAssert that the final sink bytes exactly equal the original input with no duplication or omission, and that the routine retries `EINTR` without resetting progress. Add cases for a hard error after partial progress and zero-length input.\n\nThe test must force short writes; relying on normal local files rarely exercises the required behavior.', 'verification_details': 'Must inject partial writes and EINTR deterministically, verify exact byte output/progress, and include hard-error behavior after partial completion.', 'tags': ['write', 'short-write', 'eintr', 'fault-injection']}, {'id': 'test-monotonic-timeout', 'concept': 'monotonic-timeout-clock-jump-test', 'domain': 'operating-systems', 'subdomain': 'timekeeping', 'difficulty': 'expert', 'task_type': 'testing', 'verification_method': 'rubric', 'question': 'Design a test for a timeout implementation that must not expire early or late when wall-clock time is adjusted by NTP or an administrator.', 'answer': 'Run the timeout against a monotonic clock and independently perturb the wall clock in the test environment forward and backward while the timer is active.\n\nMeasure elapsed monotonic duration from start to wakeup and assert it stays within the scheduler/timer tolerance. The wall-clock jump must not change the timeout deadline.\n\nAlso test suspend/resume semantics according to the chosen clock: some monotonic clocks exclude suspend while boot-time style clocks include it. The test should encode the intended behavior explicitly rather than assuming every monotonic source is identical.', 'verification_details': 'Must perturb wall time while measuring timeout with a monotonic source, assert elapsed monotonic duration, and explicitly test/document suspend semantics of the chosen clock.', 'tags': ['monotonic-clock', 'timeout', 'ntp', 'testing']}, {'id': 'test-prefetch-ab', 'concept': 'software-prefetch-ab-benchmark', 'domain': 'computer-architecture', 'subdomain': 'memory-performance', 'difficulty': 'advanced', 'task_type': 'testing', 'verification_method': 'rubric', 'question': 'A developer added software prefetch instructions to a pointer-heavy loop and claims they improve performance. Design an A/B benchmark that can support or reject that claim.', 'answer': 'Build two otherwise identical binaries/paths, one with the prefetch strategy and one without. Hold dataset, thread placement, compiler settings, warmup, and measurement interval constant.\n\nTest multiple dataset sizes and access patterns because a result that fits in cache says little about memory-latency hiding. Record throughput/cycles and relevant cache/TLB/memory counters. Repeat enough times to quantify variance.\n\nA useful prefetch should improve the target workload without merely moving work or bandwidth elsewhere. If extra requests increase cache pollution or memory traffic with no stable throughput gain, reject the optimization.', 'verification_details': 'Must compare controlled prefetch/no-prefetch variants across realistic working sets, collect performance plus memory/cache evidence, repeat for variance, and account for pollution/bandwidth cost.', 'tags': ['prefetch', 'benchmark', 'cache', 'memory']}, {'id': 'test-cgroup-memory-max', 'concept': 'cgroup-memory-max-oom-test', 'domain': 'linux-infrastructure', 'subdomain': 'cgroup-v2', 'difficulty': 'advanced', 'task_type': 'testing', 'verification_method': 'rubric', 'question': 'Design an integration test for a Linux service that is expected to recover cleanly after its cgroup v2 `memory.max` limit is exceeded and the process is killed.', 'answer': 'Run the real service under an isolated cgroup with a deliberately low `memory.max`, then trigger a controlled allocation workload that exceeds it.\n\nCapture `memory.events`, service exit status, journal/supervisor behavior, and persistent state. Assert that the expected process is killed/restarted according to policy, no unrelated process escapes into the same failure, and the restarted service can handle a health request.\n\nAlso verify that recovery does not loop indefinitely if normal steady-state memory already exceeds the configured limit.', 'verification_details': 'Must trigger the real memory.max failure, inspect cgroup memory events and supervisor behavior, verify clean restart/health, and detect restart loops caused by an impossible limit.', 'tags': ['cgroup-v2', 'memory.max', 'oom', 'integration-test']}, {'id': 'test-systemd-ordering', 'concept': 'systemd-dependency-order-test', 'domain': 'linux-infrastructure', 'subdomain': 'systemd', 'difficulty': 'intermediate', 'task_type': 'testing', 'verification_method': 'rubric', 'question': 'Design a test for a systemd unit that must not start until a generated credentials file is ready. The current unit occasionally starts first during boot.', 'answer': 'Boot or start the relevant target in an isolated test VM/container with the real units enabled. Instrument both the credential-producing unit and consumer with timestamps/state markers.\n\nAssert the dependency relationship that represents the actual requirement: ordering (`After=`/`Before=`) plus requirement/want semantics when startup should fail or be pulled in together. Merely adding `After=` does not cause the other unit to start.\n\nRepeat with the producer delayed and with it failing. Verify the consumer either waits and starts with valid credentials or remains stopped/fails according to policy.', 'verification_details': 'Must test real unit ordering under delayed/failing producer conditions, distinguish ordering from requirement dependencies, and assert the consumer never starts with missing credentials.', 'tags': ['systemd', 'ordering', 'dependency', 'boot']}, {'id': 'test-powercut-firmware', 'concept': 'powercut-firmware-update-recovery', 'domain': 'embedded-systems', 'subdomain': 'firmware-update', 'difficulty': 'expert', 'task_type': 'testing', 'verification_method': 'rubric', 'question': 'Design a hardware-in-the-loop test for an A/B firmware updater. Power can fail at any point while downloading, writing, or switching the active slot.', 'answer': 'Automate repeated update attempts while cutting power at randomized and boundary points: before erase, during page programming, after image write but before metadata commit, and while switching boot metadata.\n\nOn every reboot, assert that the bootloader selects either the previous verified image or a fully verified new image. Corrupt/incomplete slots must never be marked bootable solely because writing began.\n\nVerify image hashes/signatures, monotonic/version policy, bounded boot-attempt counters, and rollback after a new image fails its health milestone. Track flash-wear implications of repeated metadata updates.', 'verification_details': 'Must inject power loss across data and metadata phases, require boot only of complete verified images, test rollback/health milestones, and include metadata integrity/wear considerations.', 'tags': ['firmware', 'power-cut', 'ab-update', 'bootloader']}, {'id': 'test-reorder-loss-duplicate', 'concept': 'network-reorder-loss-duplicate-test', 'domain': 'networking', 'subdomain': 'protocol-testing', 'difficulty': 'advanced', 'task_type': 'testing', 'verification_method': 'rubric', 'question': 'A custom reliable application protocol runs over an unreliable datagram transport. Design a network-emulation test for packet loss, duplication, and reordering.', 'answer': 'Place the peers behind a controllable network emulator and apply deterministic profiles for loss, duplication, delay, and reordering, including burst loss rather than only independent random loss.\n\nSend data with known sequence/content and assert application-level properties: no duplicate delivery, correct ordering if the protocol promises it, eventual completion within retry limits, and bounded memory under missing packets.\n\nCapture protocol retransmission/ack state so a failure can be diagnosed. Include a test where the network never recovers and verify the protocol terminates or reports failure rather than retrying forever.', 'verification_details': "Must inject deterministic loss/duplication/reordering including bursts, verify the protocol's delivery guarantees and bounded resources, and test unrecoverable failure behavior.", 'tags': ['network-emulation', 'loss', 'reordering', 'reliability']}, {'id': 'test-partition-linearizability', 'concept': 'partition-leader-linearizability-test', 'domain': 'distributed-systems', 'subdomain': 'consistency-testing', 'difficulty': 'expert', 'task_type': 'testing', 'verification_method': 'rubric', 'question': 'Design a fault-injection test for a replicated register that claims linearizable reads and writes during leader failures and network partitions.', 'answer': 'Generate concurrent timestamped read/write operations from multiple clients while injecting controlled partitions, leader termination, recovery, and delayed messages.\n\nRecord invocation and completion intervals plus returned values. After the run, feed the history to a linearizability checker for a single-register model rather than judging correctness from logs by eye.\n\nInclude partitions that isolate the old leader from a majority, failover to a new leader, and healing of the partition. Operations may legitimately fail or time out depending on the availability policy, but completed successful operations must fit one legal linearized order.', 'verification_details': 'Must generate concurrent histories under partition/leader faults, record invocation/completion intervals, use a linearizability checker/model, and distinguish allowed failures from invalid successful histories.', 'tags': ['linearizability', 'partition', 'leader', 'fault-injection']}, {'id': 'test-grad-scaler', 'concept': 'mixed-precision-grad-scaler-test', 'domain': 'compute-model-infrastructure', 'subdomain': 'mixed-precision', 'difficulty': 'advanced', 'task_type': 'testing', 'verification_method': 'rubric', 'question': 'Design a test for automatic loss scaling in mixed-precision training so overflowed gradients do not silently corrupt optimizer state.', 'answer': 'Create one case with finite gradients and one controlled case that produces FP16/BF16 overflow or non-finite gradients.\n\nFor the finite case, assert that gradients are unscaled correctly and the optimizer step occurs. For the overflow case, assert that the step is skipped, model/optimizer state is not advanced as if a valid update occurred, and the scale is reduced according to policy.\n\nThen run subsequent finite steps and verify scale recovery/growth behavior. Compare selected parameters against a higher-precision reference on a small deterministic problem within expected tolerance.', 'verification_details': 'Must test both finite and overflow paths, verify skipped optimizer update on non-finite gradients, check scale adjustment/recovery, and compare against a deterministic higher-precision reference where practical.', 'tags': ['mixed-precision', 'loss-scaling', 'overflow', 'training']}]

FAMILIES = [
    {
        "id": x["id"],
        "concept": x["concept"],
        "domain": x["domain"],
    }
    for x in CATALOG
]

BY_ID = {x["id"]: x for x in CATALOG}

def build(family, rng, rid, _difficulty):
    x = BY_ID[family["id"]]
    return record(
        rid,
        x["domain"],
        x["subdomain"],
        x["task_type"],
        x["difficulty"],
        x["question"],
        x["answer"],
        x["verification_method"],
        x["verification_details"],
        x["tags"],
    )

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--records", type=int, default=len(FAMILIES))
    ap.add_argument("--seed", type=int, default=20260914)
    args = ap.parse_args()
    run_purpose(
        purpose=PURPOSE,
        families=FAMILIES,
        build=build,
        records_requested=args.records,
        seed=args.seed,
    )

if __name__ == "__main__":
    main()
